'use strict';
const $=s=>document.querySelector(s);
const I=(n,c='')=>`<svg class="ico ${c}" viewBox="0 0 24 24" aria-hidden="true">${iconShapes[n]||iconShapes.heart}</svg>`;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const today=()=>new Date().toLocaleDateString('en-CA');const dateNL=()=>new Date().toLocaleDateString('nl-NL',{weekday:'short',day:'numeric',month:'short'});const nf=(n,d=0)=>Number(n).toLocaleString('nl-NL',{minimumFractionDigits:d,maximumFractionDigits:d});
const initial={onboarded:false,name:'VYRO-gebruiker',profilePhoto:'',customSounds:[],steps:0,stepDate:today(),goals:{steps:10000,kcal:2400,protein:150,carbs:300,fat:80,water:2000,sleep:8,distance:10},water:0,waterDate:today(),meals:[],sleep:[],activities:[],alarms:[{id:1,time:'07:00',days:[1,2,3,4,5],on:false,label:'Werkweek'},{id:2,time:'08:30',days:[0,6],on:false,label:'Weekend'}],bedtime:'23:00',bedReminder:false,likes:[],notifications:false};
let state;try{state={...initial,...JSON.parse(localStorage.getItem('vyro-v1')||'null')};state.goals={...initial.goals,...state.goals}}catch{state=structuredClone(initial)}if(state.stepDate!==today()){state.steps=0;state.stepDate=today()}if(state.waterDate!==today()){state.water=0;state.waterDate=today()}
let page=state.onboarded?'today':'welcome',filter='Alle',healthTab='nutrition',period='week',communityTab='Vrienden',record={active:false,paused:false,seconds:0,distance:0,points:[],type:'Hardlopen',gps:'Nog niet gestart',watch:null},foodQuery='',selectedMeal='Lunch',selectedActivity=+(sessionStorage.getItem('vyro-selected')||0)||null;
const save=()=>localStorage.setItem('vyro-v1',JSON.stringify(state));const dailyMeals=()=>state.meals.filter(x=>x.date===today());const sum=(arr,k)=>arr.reduce((a,x)=>a+(+x[k]||0),0);const totalKm=()=>sum(state.activities,'distance');
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>$('#toast').classList.remove('show'),3200)}
function nav(){const active=['nutrition','food','sleep','alarm','health'].includes(page)?'health':['activities','record','detail','insights'].includes(page)?'activities':page;return `<nav class="nav" aria-label="Hoofdnavigatie">${[['today','home','Vandaag'],['activities','run','Bewegen'],['record','play','Start'],['health','heart','Gezondheid'],['profile','user','Profiel']].map(([p,i,t])=>`<button data-go="${p}" class="${active===p?'active':''}">${p==='record'?`<span class="startbubble">${I(i)}</span>`:I(i)}<span>${t}</span></button>`).join('')}</nav>`}
function header(title,subtitle='',action=''){return `<header class="head"><div><h1>${title}</h1>${subtitle?`<div class="sub">${subtitle}</div>`:''}</div>${action||`<button class="iconbtn" data-action="calendar" aria-label="Dagoverzicht">${I('calendar')}</button>`}</header>`}
function btn(t,action,cls=''){return `<button class="btn ${cls}" data-action="${action}">${t}</button>`}function goBtn(t,p,cls=''){return `<button class="btn ${cls}" data-go="${p}">${t}</button>`}function section(t,a=''){return `<div class="section"><h2>${t}</h2>${a}</div>`}function prog(value,max,cls=''){return `<div class="progress ${cls}"><i style="width:${Math.min(100,value/max*100)}%"></i></div>`}function toggle(on,action,id=''){return `<button class="toggle ${on?'on':''}" role="switch" aria-checked="${!!on}" aria-label="Inschakelen" data-action="${action}" data-id="${id}"></button>`}
function map(mini=false,points=[]){let line=points.length>1?points.map((p,i)=>{const xs=points.map(q=>q[1]),ys=points.map(q=>q[0]);return `${25+(p[1]-Math.min(...xs))/(Math.max(...xs)-Math.min(...xs)||1)*350},${225-(p[0]-Math.min(...ys))/(Math.max(...ys)-Math.min(...ys)||1)*185}`}).join(' '):'';return `<div class="map ${mini?'mini':''}"><svg viewBox="0 0 400 270" preserveAspectRatio="xMidYMid slice"><rect width="400" height="270" fill="#e9ece1"/><path d="M0 0h95l-35 100H0m310 30h90v150H300l-30-80M120 180l65-25 45 60-30 55H90" fill="#d3e2bc"/><path d="M270-20q-50 90-10 145t-30 160" fill="none" stroke="#afcfdd" stroke-width="12"/>${Array.from({length:10},(_,i)=>`<path d="M${i*53-120} -20 ${i*53+65} 300" stroke="#fff" stroke-width="${i%3===0?9:5}"/><path d="M-20 ${i*40-80} 420 ${i*40+80}" stroke="#fff" stroke-width="${i%3===0?8:4}"/>`).join('')}<path d="M0 220Q170 80 400 160" stroke="#e4d8ae" stroke-width="14" fill="none"/><path d="M0 220Q170 80 400 160" stroke="#fff" stroke-width="8" fill="none"/>${line?`<polyline points="${line}" stroke="#fff" stroke-width="7" fill="none"/><polyline points="${line}" stroke="#b1e600" stroke-width="4" fill="none"/>`:''}<text x="155" y="141" font-family="Ubuntu" font-size="17" fill="#4b5146">${points.length?'Jouw route':'Eindhoven'}</text>${line?`<circle cx="${line.split(' ')[0].split(',')[0]}" cy="${line.split(' ')[0].split(',')[1]}" r="5" fill="#9ad800" stroke="white" stroke-width="3"/>`:''}</svg>${!mini?'<span class="maplabel">Schematische kaart • GPS-route op schaal</span>':''}</div>`}
function bars(values,lav=false){const max=Math.max(...values,1);return `<div class="bars ${lav?'lav':''}">${values.map((v,i)=>`<div class="bar" style="--h:${Math.max(2,v/max*100)}%" title="${nf(v,1)}"><span>${['ma','di','wo','do','vr','za','zo'][i]}</span></div>`).join('')}</div>`}function weekly(key){let a=Array(7).fill(0);state.activities.forEach(x=>{if(Date.now()-new Date(x.date).getTime()<7*864e5)a[(new Date(x.date).getDay()+6)%7]+=x[key]||0});return a}
function todayPage(){const m=dailyMeals(),sleep=state.sleep.at(-1),pct=Math.min(100,Math.round(state.steps/state.goals.steps*100));return header('Vandaag',dateNL())+`<main class="main stack"><button class="card lime hero row between" data-action="steps" style="text-align:left"><div>${I('shoe')}<strong>${nf(state.steps)} <span style="font-size:23px">stappen</span></strong><small>Doel ${nf(state.goals.steps)}</small></div><div class="ring" style="--p:${pct}%"><span>${pct}%</span></div></button><div class="grid"><button class="card stat" data-go="activities"><span class="label">${I('pin')} Vandaag</span><strong>${nf(sum(state.activities.filter(x=>x.date.slice(0,10)===today()),'distance'),1)} km</strong></button><button class="card stat" data-go="activities"><span class="label">${I('flame')} Activiteit</span><strong>${nf(sum(state.activities.filter(x=>x.date.slice(0,10)===today()),'kcal'))} kcal</strong></button><button class="card stat purple" data-go="sleep"><span class="label">${I('moon')} Slaap</span><strong>${sleep?duration(sleep.hours*3600,true):'Nog geen nacht'}</strong><small>${sleep?esc(sleep.start)+' – '+esc(sleep.end):'Voeg je slaap toe'}</small></button><button class="card stat" data-go="nutrition"><span class="label">${I('food')} Voeding</span><strong>${nf(sum(m,'kcal'))} kcal</strong><small>van ${nf(state.goals.kcal)} kcal</small></button></div><button class="card row" data-action="plan" style="text-align:left"><span class="thumb">${I('run')}</span><div style="flex:1"><small>Volgende training</small><h3>Plan jouw moment</h3><small class="muted">Hardlopen, fietsen of wandelen</small></div>${I('arrow')}</button><button class="card row" data-go="insights" style="text-align:left">${I('heart')}<div style="flex:1"><small>Jouw ritme</small><h3>Bekijk je voortgang</h3></div><span style="color:#9dbd21">▂ ▃ ▅ ▆</span></button>${goBtn(I('play')+' Start activiteit','record')}<div class="row between"><button class="textbtn" data-go="community">${I('people')} Community</button><button class="textbtn" data-go="insights">Alle inzichten ${I('arrow')}</button></div></main>`}
function activityRow(x){return `<button class="listrow" data-activity="${x.id}">${I(x.type==='Fietsen'?'bike':'run')}<div><strong>${esc(x.title)}</strong><small>${nf(x.distance,2)} km · ${duration(x.seconds)} · ${pace(x.distance,x.seconds)} /km</small><small>${new Date(x.date).toLocaleDateString('nl-NL',{day:'numeric',month:'short'})} · ${esc(x.type)}</small></div>${map(true,x.points)}</button>`}
function activitiesPage(){const arr=state.activities.filter(x=>filter==='Alle'||x.type===filter);return header('Activiteiten','Jouw beweging, op één plek',`<button class="iconbtn" data-go="community" aria-label="Community">${I('people')}</button>`)+`<main class="main"><div class="chips">${['Alle','Hardlopen','Fietsen','Wandelen'].map(t=>`<button class="chip ${filter===t?'selected':''}" data-filter="${t}">${I(t==='Fietsen'?'bike':'run')}${t}</button>`).join('')}</div><div class="spacer"></div><div class="card"><small>Deze week</small><div class="row between"><strong class="bigvalue">${nf(weekly('distance').reduce((a,b)=>a+b,0),1)} km</strong><span class="tag">${state.activities.length} activiteiten</span></div>${bars(weekly('distance'))}</div>${section('Activiteitsgeschiedenis',`<button class="textbtn" data-action="manualActivity">+ Handmatig</button>`)}<div class="card listcard">${arr.length?arr.slice().reverse().map(activityRow).join(''):`<div class="empty">${I('run')}<p>Jouw eerste meters beginnen hier.<br>Neem een training op of voeg er één toe.</p></div>`}</div><div class="spacer"></div>${goBtn(I('play')+' Start activiteit','record')}</main>`}
function duration(s,words=false){const h=Math.floor(s/3600),m=Math.floor(s%3600/60),sec=Math.floor(s%60);return words?`${h} u ${m} min`:h?`${String(h).padStart(2,'0')}:${String(m).padStart(2,'0')}:${String(sec).padStart(2,'0')}`:`${String(m).padStart(2,'0')}:${String(sec).padStart(2,'0')}`}function pace(km,s){if(!km)return '–:–';let p=Math.round(s/km);return `${Math.floor(p/60)}:${String(p%60).padStart(2,'0')}`}
function recordPage(){return header('Opnemen','',`<button class="iconbtn" data-action="recordInfo" aria-label="GPS informatie">${I('gear')}</button>`)+`<main class="main"><div class="chips">${['Hardlopen','Fietsen','Wandelen'].map(t=>`<button class="chip ${record.type===t?'selected':''}" data-sport="${t}">${I(t==='Fietsen'?'bike':'run')}${t}</button>`).join('')}</div><div class="spacer"></div><div style="position:relative" id="recordMap">${map(false,record.points)}<span class="livegps" id="gpsStatus"><i class="statusdot"></i>${esc(record.gps)}</span></div><div class="timer" id="timer">${duration(record.seconds)}</div><div class="metrics"><div><strong id="liveDistance">${nf(record.distance,2)} km</strong><small>Afstand</small></div><div><strong id="livePace">${pace(record.distance,record.seconds)}</strong><small>Tempo /km</small></div><div><strong>—</strong><small>Hartslag · niet gekoppeld</small></div></div>${record.active?`<div class="two">${btn(I(record.paused?'play':'pause')+(record.paused?' Hervatten':' Pauze'),'pause','secondary')}${btn(I('stop')+' Stop','stop')}</div>`:btn(I('play')+' Start training','start')}<p class="notice">GPS meet je route met jouw toestemming. Houd de app geopend voor betrouwbare opname. Geen GPS? Gebruik de timer en vul je afstand bij het opslaan in.</p></main>`}
function detailPage(){const x=state.activities.find(x=>x.id===selectedActivity);if(!x)return activitiesPage();return header(esc(x.title),new Date(x.date).toLocaleString('nl-NL',{dateStyle:'medium',timeStyle:'short'}),`<button class="iconbtn" data-go="activities" aria-label="Terug">${I('back')}</button>`)+`<main class="main">${map(false,x.points)}<div class="metrics"><div><strong>${nf(x.distance,2)} km</strong><small>Afstand</small></div><div><strong>${duration(x.seconds)}</strong><small>Duur</small></div><div><strong>${pace(x.distance,x.seconds)}</strong><small>Tempo /km</small></div></div><div class="card"><div class="row between"><h3>Details</h3><span class="tag">${esc(x.type)}</span></div><div class="listrow"><div><small>Calorieën · schatting</small><strong>${nf(x.kcal)} kcal</strong></div>${I('flame')}</div><div class="listrow"><div><small>Registratie</small><strong>${x.points.length>1?'GPS-opname':'Handmatig / timer'}</strong></div>${I('pin')}</div>${x.note?`<p class="notice">${esc(x.note)}</p>`:''}</div>${section('Tempo per kilometer')}<div class="card"><p class="notice">${x.points.length>1?'De route is vastgelegd. Gedetailleerde tussentijden komen in een volgende versie.':'Geen GPS-tussentijden beschikbaar voor deze activiteit.'}</p></div><div class="spacer"></div><div class="two">${btn(I('share')+' Delen','share','outline')}${btn(I('download')+' GPX','gpx','outline')}</div><div class="spacer"></div>${btn('Activiteit verwijderen','deleteActivity','danger')}</main>`}
function nutritionPage(){const m=dailyMeals(),k=sum(m,'kcal');return header('Voeding',dateNL())+`<main class="main"><div class="card"><div class="row">${I('food')}<strong style="font-size:27px">${nf(k)}</strong><span>/ ${nf(state.goals.kcal)} kcal</span></div>${prog(k,state.goals.kcal)}<div class="spacer"></div>${[['Eiwitten','protein','g'],['Koolhydraten','carbs','g'],['Vetten','fat','g']].map(([n,key,u])=>`<div class="row between small"><strong>${n}</strong><span>${nf(sum(m,key))} / ${state.goals[key]} ${u}</span></div>${prog(sum(m,key),state.goals[key],key==='fat'?'lav':'')}`).join('')}</div><div class="spacer"></div><div class="card listcard">${[['Ontbijt','🥣'],['Lunch','🥗'],['Avondeten','🍲'],['Tussendoor','🍎']].map(([n,em])=>`<button class="listrow" data-meal="${n}"><span class="foodicon">${em}</span><div><strong>${n}</strong><small>${nf(sum(m.filter(x=>x.meal===n),'kcal'))} kcal · ${m.filter(x=>x.meal===n).length} producten</small></div>${I('arrow')}</button>`).join('')}</div><div class="spacer"></div><button class="card" data-action="water" style="width:100%;text-align:left"><div class="row between"><strong>${I('drop')} Water</strong><small>${nf(state.water/1000,1)} / ${nf(state.goals.water/1000,1)} L</small></div>${prog(state.water,state.goals.water,'blue')}<small class="muted">Tik om een glas toe te voegen</small></button><div class="spacer"></div>${goBtn(I('plus')+' Maaltijd toevoegen','food')}${m.length?section('Vandaag toegevoegd')+`<div class="card listcard">${m.map(x=>`<div class="listrow"><div><strong>${esc(x.name)}</strong><small>${esc(x.meal)} · ${nf(x.grams)} g · ${nf(x.kcal)} kcal</small></div><button class="iconbtn" data-delete-food="${x.id}" aria-label="Verwijderen">${I('close')}</button></div>`).join('')}</div>`:''}</main>`}
const foods=[{name:'Havermout',emoji:'🥣',kcal:380,protein:13,carbs:60,fat:7},{name:'Banaan',emoji:'🍌',kcal:89,protein:1.1,carbs:23,fat:.3},{name:'Magere kwark',emoji:'🥛',kcal:58,protein:10,carbs:4,fat:.2},{name:'Volkorenbrood',emoji:'🍞',kcal:234,protein:9,carbs:40,fat:3},{name:'Kipfilet (bereid)',emoji:'🍗',kcal:165,protein:31,carbs:0,fat:3.6},{name:'Rijst (gekookt)',emoji:'🍚',kcal:130,protein:2.7,carbs:28,fat:.3},{name:'Ei (gekookt)',emoji:'🥚',kcal:155,protein:13,carbs:1.1,fat:11},{name:'Appel',emoji:'🍎',kcal:52,protein:.3,carbs:14,fat:.2},{name:'Pindakaas',emoji:'🥜',kcal:620,protein:25,carbs:13,fat:52},{name:'Broccoli',emoji:'🥦',kcal:34,protein:2.8,carbs:7,fat:.4},{name:'Avocado',emoji:'🥑',kcal:160,protein:2,carbs:9,fat:15},{name:'Zalm (bereid)',emoji:'🐟',kcal:206,protein:22,carbs:0,fat:12}];
function foodResults(){return foods.filter(x=>x.name.toLowerCase().includes(foodQuery.toLowerCase())).map(x=>`<button class="listrow" data-food="${foods.indexOf(x)}"><span class="foodicon">${x.emoji}</span><div><strong>${x.name}</strong><small>100 g · ${x.kcal} kcal</small></div>${I('plus')}</button>`).join('')||'<div class="empty">Geen product gevonden. Voeg het zelf toe.</div>'}
function foodPage(){return header('Maaltijd toevoegen','',`<button class="iconbtn" data-go="nutrition" aria-label="Terug">${I('back')}</button>`)+`<main class="main"><select class="input" id="mealSelect" aria-label="Maaltijd">${['Ontbijt','Lunch','Avondeten','Tussendoor'].map(t=>`<option ${t===selectedMeal?'selected':''}>${t}</option>`).join('')}</select><div class="spacer"></div><div class="search">${I('search')}<input class="input" id="foodSearch" placeholder="Zoek een product" value="${esc(foodQuery)}"></div><div class="spacer"></div>${btn(I('barcode')+' Barcode scannen','barcode','outline')}<div class="spacer"></div>${btn(I('plus')+' Eigen product toevoegen','customFood','outline')}${section('Producten',`<span class="muted small">Voedingswaarden per 100 g</span>`)}<div class="card listcard" id="foodResults">${foodResults()}</div><p class="notice">Voedingswaarden zijn gemiddelden. Gebruik het etiket voor jouw exacte product.</p></main>`}
function sleepPage(){const s=state.sleep.at(-1),hours=s?.hours||0;let week=Array(7).fill(0);state.sleep.forEach(x=>{if(Date.now()-new Date(x.date).getTime()<7*864e5)week[(new Date(x.date).getDay()+6)%7]=x.hours});return header('Slaap','Rust is ook vooruitgang',`<button class="iconbtn" data-go="alarm" aria-label="Wekker">${I('clock')}</button>`)+`<main class="main stack"><div class="card purple"><div class="row">${I('moon')}<div><strong class="bigvalue">${s?duration(hours*3600,true):'Jouw nachtrust'}</strong><p class="small" style="margin-top:7px">${s?esc(s.start)+' – '+esc(s.end):'Voeg je afgelopen nacht toe'}</p></div></div></div><div class="card"><div class="row between"><h3>Deze week</h3><small class="muted">Duur per nacht</small></div>${bars(week,true)}<p class="notice">Slaap wordt handmatig geregistreerd. Slaapfasen worden niet gemeten.</p></div><button class="card row" data-action="goals" style="text-align:left">${I('flag')}<div style="flex:1"><h3>Slaapdoel</h3><small>${state.goals.sleep} uur per nacht</small></div><strong>${Math.round(hours/state.goals.sleep*100)}%</strong></button>${btn(I('plus')+' Handmatig invoeren','addSleep','outline')}<button class="card row" data-go="alarm" style="text-align:left">${I('clock')}<div style="flex:1"><h3>Wekker & bedtijd</h3><small class="muted">Maak je eigen ritme</small></div>${I('arrow')}</button><button class="card row" data-action="devices" style="text-align:left">${I('watch')}<div style="flex:1"><h3>Wearable verbinden</h3><small class="muted">Bekijk koppelingsmogelijkheden</small></div>${I('arrow')}</button>${state.sleep.length?`<div>${section('Slaapgeschiedenis')}<div class="card listcard">${state.sleep.slice(-7).reverse().map(x=>`<div class="listrow">${I('moon')}<div><strong>${duration(x.hours*3600,true)}</strong><small>${esc(x.date)} · ${esc(x.start)} – ${esc(x.end)}</small></div><button class="iconbtn" data-delete-sleep="${x.id}" aria-label="Verwijderen">${I('close')}</button></div>`).join('')}</div></div>`:''}</main>`}
function alarmPage(){return header('Wekker','Begin op jouw moment',`<button class="iconbtn" data-go="sleep" aria-label="Terug">${I('back')}</button>`)+`<main class="main stack">${state.alarms.map(x=>`<div class="card"><div class="row between"><button data-edit-alarm="${x.id}" style="text-align:left"><div class="alarm-time">${esc(x.time)}</div><strong class="small">${esc(x.label)}</strong></button>${toggle(x.on,'alarmToggle',x.id)}</div><button class="alarm-sound-label" data-edit-alarm="${x.id}">${I('music')} ${esc(soundName(x.sound||'sunrise'))} ${I('arrow')}</button><div class="weekdays">${['zo','ma','di','wo','do','vr','za'].map((d,i)=>`<span class="day ${x.days.includes(i)?'on':''}">${d}</span>`).join('')}</div></div>`).join('')}<div class="card purple"><div class="row between"><div><strong>Bedtijdherinnering</strong><p class="bigvalue">${esc(state.bedtime)}</p></div>${toggle(state.bedReminder,'bedToggle')}</div><button class="textbtn" data-action="bedtime">Tijd aanpassen ${I('arrow')}</button></div>${btn(I('plus')+' Wekker toevoegen','addAlarm','outline')}<div class="help">Testwekker: laat deze pagina open en zet het geluid aan. De browser kan geen betrouwbare wekker laten afgaan als je telefoon vergrendeld is of de app gesloten is.</div>${btn('Test het alarmgeluid','testAlarm','secondary')}</main>`}
function communityPage(){return header('Samen vooruit','Community',`<button class="iconbtn" data-action="invite" aria-label="Uitnodigen">${I('people')}</button>`)+`<main class="main"><div class="tabs">${['Vrienden','Clubs'].map(t=>`<button class="${communityTab===t?'selected':''}" data-community="${t}">${t}</button>`).join('')}</div><div class="help">Voorbeeldcommunity · onderstaande berichten tonen hoe de feed werkt. Vrienden en clubs worden gekoppeld zodra accounts beschikbaar zijn.</div><div class="spacer"></div>${communityTab==='Vrienden'?[['Sanne de Vries','Hardlopen 7,1 km','Fijne avondrun! ☀️','S',24],['Tom Jansen','Fietsen 28,4 km','Heerlijk rondje in de ochtend. 🚴','T',37]].map((x,i)=>`<div class="card feed" style="margin-bottom:13px"><div class="row"><span class="avatar small">${x[3]}</span><div><h3>${x[0]}</h3><small>${x[1]} · Voorbeeld</small></div></div><p style="margin-top:13px">${x[2]}</p>${map(false,[[51.4,5.45],[51.42,5.46],[51.41,5.49],[51.44,5.50],[51.43,5.47]])}<div class="feedfooter"><button data-like="${i}" class="${state.likes.includes(i)?'liked':''}">${I('heart')} ${x[4]+(state.likes.includes(i)?1:0)}</button><button data-comment="${i}">${I('comment')} Reageren</button></div></div>`).join(''):`<div class="card empty">${I('people')}<h3>Samen kilometers maken</h3><p>Je hebt nog geen clubs.<br>De clubfunctie volgt met gedeelde accounts.</p></div>`}<div class="card"><h3>${I('trophy')} November 50 km</h3><small>Jouw persoonlijke challenge</small>${prog(totalKm(),50)}<small>${nf(totalKm(),1)} / 50 km</small></div><div class="spacer"></div>${btn(I('share')+' Nodig iemand uit','invite','outline')}</main>`}
function insightsPage(){const km=totalKm(),week=weekly('distance'),sleep=state.sleep.at(-1);return header('Inzichten','Elk beetje telt',`<button class="iconbtn" data-action="export" aria-label="Gegevens exporteren">${I('download')}</button>`)+`<main class="main stack"><div class="tabs">${['week','alles'].map(t=>`<button data-period="${t}" class="${period===t?'selected':''}">${t==='week'?'Deze week':'Alles'}</button>`).join('')}</div><div class="grid"><div class="card stat"><span class="label">${I('run')} Afstand</span><strong>${nf(period==='week'?sum(week.map(distance=>({distance})),'distance'):km,1)} km</strong><small>Totaal ${period==='week'?'deze week':''}</small></div><button class="card stat" data-action="steps"><span class="label">${I('shoe')} Stappen</span><strong>${nf(state.steps)}</strong><small>Vandaag</small></button></div><div class="card"><h3>Afstand · afgelopen 7 dagen</h3>${bars(week)}</div><div class="card"><div class="row between"><h3>Slaapduur</h3><span class="tag">${sleep?duration(sleep.hours*3600,true):'Nog geen data'}</span></div>${bars(Array.from({length:7},(_,i)=>{const day=new Date();day.setDate(day.getDate()-(day.getDay()+6-i)%7);const key=day.toLocaleDateString('en-CA');return state.sleep.filter(x=>x.date===key).at(-1)?.hours||0}),true)}</div><div class="grid"><div class="card stat"><span class="label">${I('run')} Activiteit</span><strong>${state.activities.length}</strong><small>Trainingen opgeslagen</small></div><div class="card stat"><span class="label">${I('food')} Voeding</span><strong>${nf(sum(dailyMeals(),'kcal'))}</strong><small>kcal vandaag</small></div></div><button class="card lime" data-action="goals" style="text-align:left"><h3>${I('flag')} Jouw afstandsdoel</h3><div class="row between" style="margin-top:12px"><strong>${state.goals.distance} km bewegen</strong><small>${nf(km,1)} / ${state.goals.distance} km</small></div>${prog(km,state.goals.distance)}</button></main>`}
function profilePage(){return header('Mijn profiel','',`<button class="iconbtn" data-action="editProfile" aria-label="Profiel bewerken">${I('gear')}</button>`)+`<main class="main"><button class="row" data-action="editProfile" style="text-align:left;width:100%">${avatarMarkup()}<div style="flex:1"><h3>${esc(state.name)}</h3><small class="muted">Jouw VYRO testprofiel</small></div>${I('arrow')}</button><div class="spacer"></div><div class="card row"><div class="badge">${I('trophy')}<strong>${Math.floor(totalKm()/50)}</strong><small>Challenges</small></div><div class="badge">${I('flag')}<strong>${[state.activities.length>0,totalKm()>=10,state.sleep.length>0,state.meals.length>0].filter(Boolean).length}</strong><small>Badges</small></div><div class="badge">${I('heart')}<strong>${state.activities.length}</strong><small>Activiteiten</small></div></div><div class="spacer"></div><div class="card listcard">${[['Doelen','flag','goals'],['Gekoppelde apparaten','watch','devices'],['Meldingen','bell','notifications'],['Privacy & gegevens','lock','privacy'],['Account','user','account']].map(([t,i,a])=>`<button class="listrow" data-action="${a}">${I(i)}<div><strong>${t}</strong></div>${I('arrow')}</button>`).join('')}</div><div class="spacer"></div>${goBtn(I('chart')+' Mijn inzichten','insights','outline')}<div class="spacer"></div>${goBtn(I('people')+' Community','community','outline')}<p class="notice" style="text-align:center">VYRO · testversie 1.0<br>Jouw ritme. Jouw vooruitgang.</p></main>`}
function healthPage(){return header('Gezondheid','Zorg voor jouw ritme')+`<main class="main stack">${[['Voeding','Calorieën, maaltijden & water','food','nutrition',''],['Slaap','Jouw nachtrust & slaapdoel','moon','sleep','purple'],['Wekker','Wakker worden op jouw moment','clock','alarm',''],['Inzichten','Bekijk je voortgang','chart','insights','lime']].map(([t,s,i,p,c])=>`<button class="card row ${c}" data-go="${p}" style="text-align:left;min-height:105px">${I(i)}<div style="flex:1"><h2>${t}</h2><p class="small" style="margin-top:7px">${s}</p></div>${I('arrow')}</button>`).join('')}</main>`}
function welcomePage(){return `<div class="welcome"><img class="logo" src="assets/logo.svg" alt="VYRO"><h1>Jouw ritme.<br>Jouw<br>vooruitgang.</h1><p>Beweeg, eet gezonder, slaap beter en volg alles op één plek.<br>Samen, met VYRO.</p><div class="welcome-art"><img class="welcome-source" src="assets/design-reference.png" alt="Hardloper met limegroene route uit het VYRO-ontwerp"></div>${btn('Aan de slag '+I('arrow'),'onboard')}${btn('Over deze testversie','about','secondary')}</div>`}
function render(){if(selectedActivity)sessionStorage.setItem('vyro-selected',String(selectedActivity));history.replaceState(null,'','#'+page);const pages={today:todayPage,activities:activitiesPage,record:recordPage,detail:detailPage,nutrition:nutritionPage,food:foodPage,sleep:sleepPage,alarm:alarmPage,community:communityPage,insights:insightsPage,profile:profilePage,health:healthPage,welcome:welcomePage};$('#app').innerHTML=`<aside class="desktop-brand"><img src="assets/logo.svg" alt="VYRO"><p>SPORT. EET. SLAAP. HERHAAL.<br>Jouw ritme. Jouw vooruitgang.</p><p class="toplink">MOBIELE TESTVERSIE / 01</p></aside><div class="app ${page==='welcome'?'welcome-shell':''}">${(pages[page]||todayPage)()}${page==='welcome'?'':nav()}</div>`;save()}
function go(p){page=p;render();window.scrollTo(0,0);history.replaceState(null,'','#'+p)}
function modal(title,body){$('#modal').innerHTML=`<button class="iconbtn close" data-action="close" aria-label="Sluiten">${I('close')}</button><h2>${title}</h2>${body}`;$('#modal').showModal()}
function form(title,body,onSubmit){modal(title,`<form id="activeForm">${body}<button class="btn" type="submit">Opslaan ${I('check')}</button></form>`);$('#activeForm').onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));if(onSubmit(d)!==false){$('#modal').close();save();render();toast('Opgeslagen')}}}
const field=(label,name,type,value,extra='')=>`<label for="f-${name}">${label}</label><input class="input" id="f-${name}" name="${name}" type="${type}" value="${esc(value??'')}" ${extra}>`;
function foodForm(idx){const x=foods[idx];form(x.name,`<p>${x.kcal} kcal per 100 gram</p>${field('Hoeveel gram?','grams','number',100,'min="1" max="10000" step="1" required')}<p class="notice">Toevoegen aan ${esc(selectedMeal)}</p>`,d=>{const q=+d.grams/100;state.meals.push({id:Date.now(),date:today(),meal:selectedMeal,name:x.name,grams:+d.grams,kcal:Math.round(x.kcal*q),protein:x.protein*q,carbs:x.carbs*q,fat:x.fat*q});page='nutrition'})}
function addSleep(){form('Slaap toevoegen',field('Datum wakker geworden','date','date',today(),'required')+field('Naar bed','start','time','23:00','required')+field('Wakker','end','time','07:00','required'),d=>{const a=d.start.split(':').map(Number),b=d.end.split(':').map(Number);let min=b[0]*60+b[1]-a[0]*60-a[1];if(min<=0)min+=1440;state.sleep=state.sleep.filter(x=>x.date!==d.date);state.sleep.push({id:Date.now(),...d,hours:min/60})})}
function alarmForm(id){const x=state.alarms.find(x=>x.id===id)||{time:'07:00',label:'Nieuwe wekker',days:[1,2,3,4,5],sound:'sunrise'};form('Wekker instellen',field('Tijd','time','time',x.time,'required')+field('Naam','label','text',x.label,'required maxlength="30"')+`<label for="alarmSound">Wekkergeluid</label><select class="input" name="sound" id="alarmSound">${soundOptions(x.sound||'sunrise')}</select><div class="two sound-buttons"><button class="btn outline" type="button" data-action="previewSound">${I('volume')} Voorbeeld</button><button class="btn outline" type="button" data-action="uploadRingtone">${I('upload')} Eigen ringtone</button></div><p class="notice">MP3, M4A, WAV of OGG · maximaal 20 MB. Je bestand blijft op dit apparaat.</p><label>Herhalen</label><div class="chips">${['zo','ma','di','wo','do','vr','za'].map((t,i)=>`<label class="chip"><input type="checkbox" name="day${i}" ${x.days.includes(i)?'checked':''}> ${t}</label>`).join('')}</div><p class="notice">Werkt zolang de testapp geopend is.</p>${id?`<button type="button" class="textbtn" data-delete-alarm="${id}">Wekker verwijderen</button>`:''}`,d=>{const a={id:id||Date.now(),time:d.time,label:d.label,sound:d.sound||'sunrise',days:[0,1,2,3,4,5,6].filter(i=>d['day'+i]),on:true};if(!a.days.length){toast('Selecteer minstens één dag');return false}if(id)state.alarms=state.alarms.map(v=>v.id===id?a:v);else state.alarms.push(a);enableAudio()})}
let audio;function enableAudio(){try{audio=audio||new (window.AudioContext||window.webkitAudioContext)();audio.resume()}catch{}}
function beep(sound='sunrise',preview=false){return playAlarmSound(sound,preview)}
let wakeLock;async function start(){record.active=true;record.paused=false;record.gps='GPS zoeken…';record.started=Date.now();if('geolocation'in navigator)record.watch=navigator.geolocation.watchPosition(pos=>{if(record.paused||!record.active)return;const p=[pos.coords.latitude,pos.coords.longitude];if(pos.coords.accuracy>80){record.gps='GPS onnauwkeurig';return}const prev=record.points.at(-1);if(prev){const d=haversine(prev,p);if(d>.003&&d<.3){record.distance+=d;record.points.push(p)}}else record.points.push(p);record.gps='GPS verbonden';if(page==='record')render()},()=>{record.gps='GPS niet beschikbaar';if(page==='record')render();toast('Timer loopt. Vul je afstand na afloop in.')},{enableHighAccuracy:true,maximumAge:3000,timeout:15000});else record.gps='Timer zonder GPS';try{wakeLock=await navigator.wakeLock?.request('screen')}catch{}render()}
function haversine(a,b){const r=Math.PI/180,dlat=(b[0]-a[0])*r,dlon=(b[1]-a[1])*r;return 6371*2*Math.asin(Math.sqrt(Math.sin(dlat/2)**2+Math.cos(a[0]*r)*Math.cos(b[0]*r)*Math.sin(dlon/2)**2))}
function stop(){record.paused=true;form('Training bewaren',field('Naam','title','text',record.type==='Hardlopen'?'Ochtendrun':record.type,'required maxlength="60"')+field('Afstand (km)','distance','number',record.distance.toFixed(2),'min="0" max="1000" step="0.01" required')+`<p class="notice">Duur ${duration(record.seconds)} · ${record.type}</p>`+field('Notitie','note','text','','maxlength="500"'),d=>{if(record.watch!==null)navigator.geolocation.clearWatch(record.watch);wakeLock?.release();const id=Date.now();state.activities.push({id,title:d.title,type:record.type,distance:+d.distance,seconds:Math.max(1,record.seconds),kcal:Math.round(+d.distance*(record.type==='Fietsen'?25:65)),date:new Date().toISOString(),points:record.points,note:d.note});selectedActivity=id;record={active:false,paused:false,seconds:0,distance:0,points:[],type:record.type,gps:'Nog niet gestart',watch:null};page='detail'});$('#modal').addEventListener('close',()=>{if(record.active){record.paused=false;render()}},{once:true})}
function download(name,text,type='application/json'){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),3000)}
